  getSnapshot(
    lookup: string | SnapshotLookup
  ): Promise<SessionSnapshot<State> | undefined>;

  /** Aborts a running snapshot. Requires a server store. */
  abort(snapshotId: string): Promise<SessionSnapshot['status'] | undefined>;
